using System;using System.Linq;using System.Collections.Generic;
internal static class LifecycleIntegrationTests {
 static void Check(bool v,string m){if(!v)throw new Exception(m);}static void Near(double a,double b,string m){Check(Math.Abs(a-b)<1e-10,m);}
 static SpriteMeta Mask(string n){return new SpriteMeta{originX=10,originY=12,frames=1,colliders=new[]{new SpriteCollider{left=0,top=1,right=20,bottom=22}}};}
 static Track E(){return new Track{id="e",kind="emitter",lane=0,start=0,end=0,count=1,speed=-2,life=30,x=4,y=304,scale=.5,rawAlpha=true,alpha=1,despawnBounds="sprite-mask",sprite="CWspr",advancedBullets=true};}
 static EditorState S(params Track[] ts){var s=new EditorState{duration=300,tracks=ts.ToList()};Motion.Normalize(s);return s;}
 static BulletWorld W(EditorState s){return new BulletWorld(s,new RoomData{width=800,height=608},null,Mask);}
 static void Main(){var e=E();e.bulletActions.Add(new BulletAction{type="alpha",start=0,duration=30,expression="alpha+.04"});e.bulletActions.Add(new BulletAction{type="split",start=0,duration=30,condition="age>=5",once=true,count=1});var child=E();child.id="child";child.templateOnly=true;child.x=400;e.bulletActions.Add(new BulletAction{type="spawn",start=0,duration=30,condition="age>=5",once=true,templateId="child"});var w=W(S(e,child));w.Seek(4);var parent=w.bullets.Single();Near(parent.alpha,1.2,"raw alpha before bound");w.Seek(5);Check(w.bullets.Count==0,"bound suppresses queued split and template spawn");Check(parent.dead,"parent bound dead");w.Seek(4);Check(w.bullets.Count==1,"reverse restores parent");w.Seek(5);Check(w.bullets.Count==0,"repeat bound");
 e=E();e.x=10;e.alpha=.08;e.bulletActions.Add(new BulletAction{type="alpha",start=0,duration=20,expression="alpha-.04"});e.bulletActions.Add(new BulletAction{type="clear",start=0,duration=20,condition="alpha<=0"});w=W(S(e));w.Seek(0);parent=w.bullets.Single();w.Seek(1);Check(w.bullets.Count==0,"condition clear removes");Near(parent.x,10,"clear before movement despite bound enabled");
 e=E();e.x=-4;e.speed=0;e.alpha=1.04;var copy=new Track{id="copy",kind="control",lane=1,start=2,end=2,eventPreset="group-copy",eventGroup="g",controlValue=-2,eventCopyLife=20};var s=S(e,copy);s.timelineGroups.Add(new TimelineGroup{id="g",name="g",lanes=new List<int>{0,1}});Motion.Normalize(s);w=W(s);w.Seek(2);var c=w.bullets.Single(b=>b.generation==1);Check(c.source.rawAlpha&&c.source.despawnBounds=="sprite-mask","copy preserves flags");Near(c.alpha,1.04,"copy preserves raw");w.Seek(3);Check(w.bullets.Count==1&&w.bullets[0].generation==0,"copied mask exits while original remains");
 e=E();e.despawnBounds="none";e.speed=0;e.alpha=1;e.x=100;var split=new BulletAction{type="split",start=0,duration=0,count=1,childSpeed=9};split.expressions["childSpeed"]="alpha*2";e.bulletActions.Add(split);e.bulletActions.Add(new BulletAction{type="alpha",start=0,duration=0,to=2});w=W(S(e));w.Seek(0);Near(w.bullets.Single(b=>b.generation==1).speed,2,"split samples alpha when queued, before later action");Near(w.bullets.Single(b=>b.generation==0).alpha,2,"later alpha action still executes");
 e=E();e.despawnBounds="none";e.speed=0;e.alpha=1;e.x=100;split=new BulletAction{type="split",start=0,duration=0,count=3};split.expressions["childSpeed"]="alpha+random(100)+random(100)";split.expressions["spread"]="alpha+random(30)+random(30)";e.bulletActions.Add(split);e.bulletActions.Add(new BulletAction{type="alpha",start=0,duration=0,to=2});w=W(S(e));w.Seek(0);parent=w.bullets.Single(b=>b.generation==0);var ctx=w.Context(parent,0);ctx.alpha=1;double expectedSpeed=ScalarExpressions.ActionValue(e,split,"childSpeed",ctx),expectedSpread=ScalarExpressions.ActionValue(e,split,"spread",ctx);foreach(var ch in w.bullets.Where(b=>b.generation==1)){Near(ch.speed,expectedSpeed,"random split speed sampled at queue state");Near(ch.direction,(ch.index-1)*expectedSpread,"random spread sampled at queue state");}w.Seek(1);w.Seek(0);foreach(var ch in w.bullets.Where(b=>b.generation==1))Near(ch.speed,expectedSpeed,"random split deterministic reverse");
 Console.WriteLine("PASS combined raw alpha + conditional clear + sprite-mask precedence, split/spawn suppression, group copy inheritance and reverse/repeat.");}
}
